/// <summary>
/// Vendor rebate request class
/// </summary>
[DataContractAttribute]
public final class METVendorRebateRequest
{
    DataAreaId dataAreaId;
    METVendorRebateDealContract metVendorRebateDealContract;
    METVendorRebateTableContract metVendorRebateTableContract;
    private List metVendorRebateTableContractArray;

}

Method.Source:
/// <summary>
/// Data area Id 
/// </summary>
/// <param name = "_dataAreaId">DataAreaId</param>
/// <returns>DataAreaId</returns>
[DataMember(extendedTypeStr(dataAreaId))]
public str parmDataAreaId(DataAreaId _dataAreaId = dataAreaId)
{
    if (!prmIsDefault(_dataAreaId))
    {
        dataAreaId = _dataAreaId;
    }
    return dataAreaId;
}

/// <summary>
/// Vendor rebate deal contract class
/// </summary>
/// <param name = "_metVendorRebateDealContract">METVendorRebateDealContract</param>
/// <returns>METVendorRebateDealContract</returns>
[DataMember(identifierStr(METVendorRebateDealContract))]
public METVendorRebateDealContract parmVendorRebateDealContract(METVendorRebateDealContract _metVendorRebateDealContract = metVendorRebateDealContract)
{
    if (!prmIsDefault(_metVendorRebateDealContract))
    {
        metVendorRebateDealContract = _metVendorRebateDealContract;
    }
    return metVendorRebateDealContract;
}

/// <summary>
/// METVendorRebateTableContract parameter
/// </summary>
/// <param name = "_metVendorRebateTableContractArray">List</param>
/// <returns>List</returns>
[DataMemberAttribute("METVendorRebateTableContract"),
DataCollection(Types::Class, classStr(METVendorRebateTableContract)),
AifCollectionTypeAttribute('_metVendorRebateTableContractArray', Types::Class, classStr(METVendorRebateTableContract)),
AifCollectionTypeAttribute('return', Types::Class, classStr(METVendorRebateTableContract))]
public List parmMETVendorRebateTableContractArray(List _metVendorRebateTableContractArray = metVendorRebateTableContractArray)
{
    if (!prmIsDefault(_metVendorRebateTableContractArray))
    {
        metVendorRebateTableContractArray = _metVendorRebateTableContractArray;
    }

    return metVendorRebateTableContractArray;
}
